import '../../../icons/sparkles.js';
import { Component, Element, Event, type EventEmitter, Prop, State, Watch, h } from '@stencil/core';
import { AnchoredOverlay } from '../../utils/anchored-overlay';
import { anchoredOverlayPosition } from '../../utils/anchored-overlay-layout';
import { provenanceText } from './ki-ai-label.provenance';

export type KiAiLabelSize = 'sm' | 'md';

/**
 * A compact provenance mark for AI-generated content, with optional details
 * and a user-initiated request to restore their original text.
 *
 * @whenToUse Mark text or a value generated by AI. Include the source in
 * `explanation` when people can inspect how it was generated. In a `ki-input`,
 * place the label in the `end` slot to describe the field's provenance.
 * @whenNotToUse Use a status component for active generation or processing,
 * and an application action for changes that do not restore the person's text.
 * @part label - Tinted mark containing the icon and visible text.
 * @part icon - Decorative sparkles glyph.
 * @part trigger - Disclosure button, available with an explanation.
 * @part popover - Non-modal explanation panel.
 * @part explanation - Source explanation paragraph.
 * @part metadata - Optional model and generation time.
 * @part revert - Button that requests reversion.
 */
@Component({
  tag: 'ki-ai-label',
  styleUrl: 'ki-ai-label.css',
  shadow: true,
})
export class KiAiLabel {
  // axe treats a node with a `host` property as a shadow root when scoping an audit.
  @Element() private readonly hostElement!: HTMLKiAiLabelElement;
  @State() private open = false;
  private readonly overlay = new AnchoredOverlay();
  private trigger: HTMLButtonElement | undefined;
  private popover: HTMLDivElement | undefined;

  /**
   * Plain-text explanation of how the content was generated. Supply a
   * nonblank explanation to offer disclosure. Omit it for a static mark.
   */
  @Prop() explanation?: string;

  /** Optional plain-text model name shown in the explanation. */
  @Prop() model?: string;

  /** Optional generation date or time, displayed as supplied. */
  @Prop() generatedAt?: string;

  /**
   * Offer the revert action inside the explanation. Enable it when the
   * application has the original text and handles `ki-revert`.
   * @default false
   */
  @Prop() revertible = false;

  /** Size of the painted mark. Unknown values use the small metrics. @default 'sm' */
  @Prop({ reflect: true }) size: KiAiLabelSize = 'sm';

  /** Short visible provenance text. Localize it with the trigger name. @default 'AI' */
  @Prop() label = 'AI';

  /** Accessible name of the disclosure button. Include the visible label. @default 'AI-generated: about this content' */
  @Prop() triggerLabel = 'AI-generated: about this content';

  /** Accessible name of the non-modal explanation panel. @default 'About this content' */
  @Prop() popoverLabel = 'About this content';

  /** Visible prefix for the model name. @default 'Model:' */
  @Prop() modelLabel = 'Model:';

  /** Visible prefix for the generation date or time. @default 'Generated' */
  @Prop() generatedAtLabel = 'Generated';

  /** Visible text and accessible name of the revert action. @default 'Revert to my text' */
  @Prop() revertLabel = 'Revert to my text';

  /**
   * Bubbles when a person requests their original text. Use this request
   * to restore the original from application state.
   */
  @Event({ eventName: 'ki-revert', bubbles: true, composed: true, cancelable: false })
  kiRevert!: EventEmitter<void>;

  @Watch('explanation')
  explanationChanged(): void {
    if (!provenanceText(this.explanation)) {
      this.close();
    }
  }

  disconnectedCallback(): void {
    this.close();
  }

  private close(restoreFocus = false): void {
    this.open = false;
    this.overlay.hide(restoreFocus ? true : undefined);
  }

  private toggle = (): void => {
    if (this.open) {
      this.close(true);
      return;
    }
    const { trigger, popover } = this;
    if (!trigger || !popover) {
      return;
    }
    const gap = Number.parseFloat(getComputedStyle(popover).rowGap);
    this.open = this.overlay.show(popover, trigger, {
      position: anchoredOverlayPosition({ placement: 'bottom-start', offset: gap || 0 }),
      outsidePointer: this.hostElement,
      escape: 'bubble',
      onDismiss: (reason) => {
        this.close(reason === 'escape');
      },
    });
    if (this.open) {
      popover.focus({ preventScroll: true });
    }
  };

  private leaveDisclosure = (event: FocusEvent): void => {
    const next = event.relatedTarget;
    if (next instanceof Node && next !== this.trigger && !this.popover?.contains(next)) {
      this.close();
    }
  };

  private revert = (): void => {
    this.close(true);
    this.kiRevert.emit();
  };

  render() {
    const explanation = provenanceText(this.explanation);
    const mark = (
      <span part="label">
        <ki-icon part="icon" name="sparkles" aria-hidden="true" />
        <span>{this.label}</span>
      </span>
    );
    if (!explanation) {
      return mark;
    }

    const model = provenanceText(this.model);
    const generatedAt = provenanceText(this.generatedAt);
    return [
      <button
        key="trigger"
        part="trigger"
        type="button"
        tabIndex={0}
        aria-label={this.triggerLabel}
        aria-haspopup="dialog"
        aria-expanded={String(this.open)}
        ref={(element) => {
          this.trigger = element;
        }}
        onClick={this.toggle}
        onFocusout={this.leaveDisclosure}
      >
        {mark}
      </button>,
      <div
        key="provenance"
        part="popover"
        role="dialog"
        aria-label={this.popoverLabel}
        aria-describedby="explanation"
        tabIndex={-1}
        popover="manual"
        ref={(element) => {
          this.popover = element;
        }}
        onFocusout={this.leaveDisclosure}
      >
        <p id="explanation" part="explanation">
          {explanation}
        </p>
        {model || generatedAt ? (
          <p part="metadata">
            {model ? (
              <span>
                {this.modelLabel} <bdi>{model}</bdi>
              </span>
            ) : null}
            {generatedAt ? (
              <span>
                {this.generatedAtLabel} <bdi>{generatedAt}</bdi>
              </span>
            ) : null}
          </p>
        ) : null}
        {this.revertible ? (
          <button part="revert" type="button" tabIndex={0} onClick={this.revert}>
            {this.revertLabel}
          </button>
        ) : null}
      </div>,
    ];
  }
}
